{
  "segment_function": "argument",
  "claims": [
    {
      "claim": "Marx defined labor physiologically as metabolism with nature, placing labor and consumption as stages in the cycle of biological life.",
      "claim_type": "author_position",
      "supporting_excerpt": "When Marx defined labor as “man’s metabolism with nature,” in whose process “nature’s material [is] adapted by a change of form to the wants of man,” so that “labour has incorporated itself with its subject,” he indicated clearly that he was “speaking physiologically” and that labor and consumption are but two stages of the ever-recurring cycle of biological life.",
      "support_kind": "direct",
      "qualifications": [],
      "confidence": 1
    },
    {
      "claim": "Locke, Adam Smith, and Marx elevated labor to the source of property, wealth, and productivity respectively, creating contradictions by equating work with labor.",
      "claim_type": "author_position",
      "supporting_excerpt": "The sudden, spectacular rise of labor from the lowest, most despised position to the highest rank, as the most esteemed of all human activities, began when Locke discovered that labor is the source of all property. It followed its course when Adam Smith asserted that labor was the source of all wealth and found its climax in Marx’s “system of labor,” where labor became the source of all productivity and the expression of the very humanity of man.",
      "support_kind": "direct",
      "qualifications": [],
      "confidence": 1
    }
  ],
  "definitions": [
    {
      "term": "Labor",
      "definition": "An activity whose products are meant to be consumed immediately to sustain the biological life process and which engages in a devouring process that seizes and destroys matter."
    }
  ],
  "distinctions": [
    {
      "item_a": "Labor",
      "item_b": "Work",
      "distinction": "Labor prepares matter for incorporation and eventual destruction to sustain biological life, whereas work does not prepare matter for incorporation but changes it into material in order to work upon it and use the finished product."
    }
  ],
  "references_to_other_sections": [],
  "unresolved_context": [],
  "must_not_be_lost": [
    "Labor as biological metabolism with nature.",
    "The distinction between the destructive nature of labor and the worldly durability of work.",
    "The historical elevation of labor by Locke, Smith, and Marx."
  ]
}

